preConditionHook:
// New window low above a longer low (Brian's notes ON-29-a, TRIAGE #29, p. 31).
// low[0] below the lowest low of bars 1..lookback but above the lowest low of
// bars 1..longFactor x lookback: a new short-window low that is not a new long-window low. LONG;
// short mirrors at highs. Not HighestHighBreakout (window includes bar 0, no
// outer bound). longFactor is meant to be a whole number (the EL twin passes
// the product as the Length); the (int) truncation is exact there.
// The window extremes are written out as the Extremes loop: seeded at bar 1,
// strict el_lt/el_gt scan.
longN = (int)(longFactor * lookback);
loShort = low[1];
hiShort = high[1];
for (ii = 2; ii <= (int)lookback; ++ii) {
    if (el_lt(low[ii], loShort)) loShort = low[ii];
    if (el_gt(high[ii], hiShort)) hiShort = high[ii];
}
loLong = low[1];
hiLong = high[1];
for (ii = 2; ii <= longN; ++ii) {
    if (el_lt(low[ii], loLong)) loLong = low[ii];
    if (el_gt(high[ii], hiLong)) hiLong = high[ii];
}
